window.CHUJI_DATA_5 = [{"l": 341, "lt": "Lesson 41 Going Camping 露营", "i": 1, "type": "reading", "en": "Last weekend, my classmates and I went camping.", "zh": "上个周末我和同学去露营。", "audio": "chuji_l41_01.mp3", "localAudio": "audio_chunks/chuji_l41_01.mp3", "b64": "", "src": "chuji"}, {"l": 341, "lt": "Lesson 41 Going Camping 露营", "i": 2, "type": "reading", "en": "We found a grassy spot beside a river.", "zh": "我们在河边找到一块草地。", "audio": "chuji_l41_02.mp3", "localAudio": "audio_chunks/chuji_l41_02.mp3", "b64": "", "src": "chuji"}, {"l": 341, "lt": "Lesson 41 Going Camping 露营", "i": 3, "type": "reading", "en": "We put up our tents and made a campfire.", "zh": "我们架起帐篷、生了营火。", "audio": "chuji_l41_03.mp3", "localAudio": "audio_chunks/chuji_l41_03.mp3", "b64": "", "src": "chuji"}, {"l": 341, "lt": "Lesson 41 Going Camping 露营", "i": 4, "type": "reading", "en": "Then, we fished at the river.", "zh": "然后就在河边钓鱼。", "audio": "chuji_l41_04.mp3", "localAudio": "audio_chunks/chuji_l41_04.mp3", "b64": "", "src": "chuji"}, {"l": 341, "lt": "Lesson 41 Going Camping 露营", "i": 5, "type": "reading", "en": "We had only one fishing rod, so we took turns.", "zh": "我们只有一只钓竿，因此我们就轮流钓。", "audio": "chuji_l41_05.mp3", "localAudio": "audio_chunks/chuji_l41_05.mp3", "b64": "", "src": "chuji"}, {"l": 341, "lt": "Lesson 41 Going Camping 露营", "i": 6, "type": "reading", "en": "After a while, we caught a big trout.", "zh": "没多久，我们钓到一条大鱼。", "audio": "chuji_l41_06.mp3", "localAudio": "audio_chunks/chuji_l41_06.mp3", "b64": "", "src": "chuji"}, {"l": 341, "lt": "Lesson 41 Going Camping 露营", "i": 7, "type": "reading", "en": "Finally, we sat around the fire, roasted the fish and sang songs.", "zh": "最后，我们围坐在营火旁，边烤鱼边唱歌。", "audio": "chuji_l41_07.mp3", "localAudio": "audio_chunks/chuji_l41_07.mp3", "b64": "", "src": "chuji"}, {"l": 341, "lt": "Lesson 41 Going Camping 露营", "i": 8, "type": "reading", "en": "Camping is really fun!", "zh": "露营真有趣！", "audio": "chuji_l41_08.mp3", "localAudio": "audio_chunks/chuji_l41_08.mp3", "b64": "", "src": "chuji"}, {"l": 342, "lt": "Lesson 42 Are You Having Fun? 你玩得愉快吗？", "i": 1, "type": "dialog", "en": "How often do you go camping?", "zh": "你多久去露营一次？", "audio": "chuji_l42_01.mp3", "localAudio": "audio_chunks/chuji_l42_01.mp3", "b64": "", "src": "chuji", "speaker": "Sally", "note": "说话人: Sally"}, {"l": 342, "lt": "Lesson 42 Are You Having Fun? 你玩得愉快吗？", "i": 2, "type": "dialog", "en": "This is my first time.", "zh": "这是我第一次去露营。", "audio": "chuji_l42_02.mp3", "localAudio": "audio_chunks/chuji_l42_02.mp3", "b64": "", "src": "chuji", "speaker": "Bert", "note": "说话人: Bert"}, {"l": 342, "lt": "Lesson 42 Are You Having Fun? 你玩得愉快吗？", "i": 3, "type": "dialog", "en": "Really? Are you having fun?", "zh": "真的吗？你玩得开心吗？", "audio": "chuji_l42_03.mp3", "localAudio": "audio_chunks/chuji_l42_03.mp3", "b64": "", "src": "chuji", "speaker": "Sally", "note": "说话人: Sally"}, {"l": 342, "lt": "Lesson 42 Are You Having Fun? 你玩得愉快吗？", "i": 4, "type": "dialog", "en": "Yes. I'm having a wonderful time.", "zh": "是的。我玩得开心极了。", "audio": "chuji_l42_04.mp3", "localAudio": "audio_chunks/chuji_l42_04.mp3", "b64": "", "src": "chuji", "speaker": "Bert", "note": "说话人: Bert"}, {"l": 343, "lt": "Lesson 43 Killing Two Birds with One Stone 两全其美", "i": 1, "type": "reading", "en": "Dan must take a day off tomorrow.", "zh": "丹明天必须请一天假。", "audio": "chuji_l43_01.mp3", "localAudio": "audio_chunks/chuji_l43_01.mp3", "b64": "", "src": "chuji"}, {"l": 343, "lt": "Lesson 43 Killing Two Birds with One Stone 两全其美", "i": 2, "type": "reading", "en": "He has to take care of his sick mother.", "zh": "他得照顾他生病的母亲。", "audio": "chuji_l43_02.mp3", "localAudio": "audio_chunks/chuji_l43_02.mp3", "b64": "", "src": "chuji"}, {"l": 343, "lt": "Lesson 43 Killing Two Birds with One Stone 两全其美", "i": 3, "type": "reading", "en": "He ought to talk to his boss, but he's afraid.", "zh": "他应当向他的老板说的，但我怕。", "audio": "chuji_l43_03.mp3", "localAudio": "audio_chunks/chuji_l43_03.mp3", "b64": "", "src": "chuji"}, {"l": 343, "lt": "Lesson 43 Killing Two Birds with One Stone 两全其美", "i": 4, "type": "reading", "en": "His boss might get angry with him.", "zh": "他的老板也许会生他的气。", "audio": "chuji_l43_04.mp3", "localAudio": "audio_chunks/chuji_l43_04.mp3", "b64": "", "src": "chuji"}, {"l": 343, "lt": "Lesson 43 Killing Two Birds with One Stone 两全其美", "i": 5, "type": "reading", "en": "What should Dan do?", "zh": "丹该怎么办呢？", "audio": "chuji_l43_05.mp3", "localAudio": "audio_chunks/chuji_l43_05.mp3", "b64": "", "src": "chuji"}, {"l": 343, "lt": "Lesson 43 Killing Two Birds with One Stone 两全其美", "i": 6, "type": "reading", "en": "He can take the work home.", "zh": "他可以把工作带回家去。", "audio": "chuji_l43_06.mp3", "localAudio": "audio_chunks/chuji_l43_06.mp3", "b64": "", "src": "chuji"}, {"l": 343, "lt": "Lesson 43 Killing Two Birds with One Stone 两全其美", "i": 7, "type": "reading", "en": "This way, he can kill two birds with one stone.", "zh": "这样他就能两全其美。", "audio": "chuji_l43_07.mp3", "localAudio": "audio_chunks/chuji_l43_07.mp3", "b64": "", "src": "chuji"}, {"l": 344, "lt": "Lesson 44 She Had a Bad Cold 她患了重感冒", "i": 1, "type": "dialog", "en": "Where were you yesterday?", "zh": "你昨天在哪里？", "audio": "chuji_l44_01.mp3", "localAudio": "audio_chunks/chuji_l44_01.mp3", "b64": "", "src": "chuji", "speaker": "Mary", "note": "说话人: Mary"}, {"l": 344, "lt": "Lesson 44 She Had a Bad Cold 她患了重感冒", "i": 2, "type": "dialog", "en": "I was at home. In fact, I was taking care of Sally.", "zh": "我在家里。事实上，我在照顾萨莉。", "audio": "chuji_l44_02.mp3", "localAudio": "audio_chunks/chuji_l44_02.mp3", "b64": "", "src": "chuji", "speaker": "Jack", "note": "说话人: Jack"}, {"l": 344, "lt": "Lesson 44 She Had a Bad Cold 她患了重感冒", "i": 3, "type": "dialog", "en": "What's wrong with her?", "zh": "她怎么了？", "audio": "chuji_l44_03.mp3", "localAudio": "audio_chunks/chuji_l44_03.mp3", "b64": "", "src": "chuji", "speaker": "Mary", "note": "说话人: Mary"}, {"l": 344, "lt": "Lesson 44 She Had a Bad Cold 她患了重感冒", "i": 4, "type": "dialog", "en": "She had a bad cold.", "zh": "她患了重感冒。", "audio": "chuji_l44_04.mp3", "localAudio": "audio_chunks/chuji_l44_04.mp3", "b64": "", "src": "chuji", "speaker": "Jack", "note": "说话人: Jack"}, {"l": 344, "lt": "Lesson 44 She Had a Bad Cold 她患了重感冒", "i": 5, "type": "dialog", "en": "Is she getting better?", "zh": "她好多了吗？", "audio": "chuji_l44_05.mp3", "localAudio": "audio_chunks/chuji_l44_05.mp3", "b64": "", "src": "chuji", "speaker": "Mary", "note": "说话人: Mary"}, {"l": 344, "lt": "Lesson 44 She Had a Bad Cold 她患了重感冒", "i": 6, "type": "dialog", "en": "Yes. Thanks.", "zh": "好多了。谢谢。", "audio": "chuji_l44_06.mp3", "localAudio": "audio_chunks/chuji_l44_06.mp3", "b64": "", "src": "chuji", "speaker": "Jack", "note": "说话人: Jack"}, {"l": 345, "lt": "Lesson 45 What a Nightmare! 真是恶梦一场啊！", "i": 1, "type": "reading", "en": "Jeff had a terrible day.", "zh": "杰夫过了很糟的一天。", "audio": "chuji_l45_01.mp3", "localAudio": "audio_chunks/chuji_l45_01.mp3", "b64": "", "src": "chuji"}, {"l": 345, "lt": "Lesson 45 What a Nightmare! 真是恶梦一场啊！", "i": 2, "type": "reading", "en": "He missed the train to work.", "zh": "他上班没赶上火车。", "audio": "chuji_l45_02.mp3", "localAudio": "audio_chunks/chuji_l45_02.mp3", "b64": "", "src": "chuji"}, {"l": 345, "lt": "Lesson 45 What a Nightmare! 真是恶梦一场啊！", "i": 3, "type": "reading", "en": "Moreover, he had to wait a long time for the next train.", "zh": "而且，他得久候下一班火车的到来。", "audio": "chuji_l45_03.mp3", "localAudio": "audio_chunks/chuji_l45_03.mp3", "b64": "", "src": "chuji"}, {"l": 345, "lt": "Lesson 45 What a Nightmare! 真是恶梦一场啊！", "i": 4, "type": "reading", "en": "As a matter of fact, he waited for two hours.", "zh": "事实上，他等了两个小时。", "audio": "chuji_l45_04.mp3", "localAudio": "audio_chunks/chuji_l45_04.mp3", "b64": "", "src": "chuji"}, {"l": 345, "lt": "Lesson 45 What a Nightmare! 真是恶梦一场啊！", "i": 5, "type": "reading", "en": "To make matters worse, he left his briefcase on the train.", "zh": "更糟的是，他把手提箱留在火车上了。", "audio": "chuji_l45_05.mp3", "localAudio": "audio_chunks/chuji_l45_05.mp3", "b64": "", "src": "chuji"}, {"l": 345, "lt": "Lesson 45 What a Nightmare! 真是恶梦一场啊！", "i": 6, "type": "reading", "en": "As a result, he had to go to the police station.", "zh": "结果，他得到警察局走一趟。", "audio": "chuji_l45_06.mp3", "localAudio": "audio_chunks/chuji_l45_06.mp3", "b64": "", "src": "chuji"}, {"l": 345, "lt": "Lesson 45 What a Nightmare! 真是恶梦一场啊！", "i": 7, "type": "reading", "en": "Poor Jeff never got to work that day.", "zh": "可怜的杰夫那一天根本上不了班。", "audio": "chuji_l45_07.mp3", "localAudio": "audio_chunks/chuji_l45_07.mp3", "b64": "", "src": "chuji"}, {"l": 346, "lt": "Lesson 46 A Terrible Headache 头痛得很厉害", "i": 1, "type": "dialog", "en": "Do you have any aspirins?", "zh": "你有阿司匹林吗？", "audio": "chuji_l46_01.mp3", "localAudio": "audio_chunks/chuji_l46_01.mp3", "b64": "", "src": "chuji", "speaker": "Frank", "note": "说话人: Frank"}, {"l": 346, "lt": "Lesson 46 A Terrible Headache 头痛得很厉害", "i": 2, "type": "dialog", "en": "In fact, I don't. Why?", "zh": "事实上，我没有。干嘛问这个？", "audio": "chuji_l46_02.mp3", "localAudio": "audio_chunks/chuji_l46_02.mp3", "b64": "", "src": "chuji", "speaker": "Jane", "note": "说话人: Jane"}, {"l": 346, "lt": "Lesson 46 A Terrible Headache 头痛得很厉害", "i": 3, "type": "dialog", "en": "I have a terrible headache.", "zh": "我头痛得很厉害。", "audio": "chuji_l46_03.mp3", "localAudio": "audio_chunks/chuji_l46_03.mp3", "b64": "", "src": "chuji", "speaker": "Frank", "note": "说话人: Frank"}, {"l": 346, "lt": "Lesson 46 A Terrible Headache 头痛得很厉害", "i": 4, "type": "dialog", "en": "Well, you should go see a doctor immediately.", "zh": "那么，你应当立刻去看医生。", "audio": "chuji_l46_04.mp3", "localAudio": "audio_chunks/chuji_l46_04.mp3", "b64": "", "src": "chuji", "speaker": "Jane", "note": "说话人: Jane"}, {"l": 347, "lt": "Lesson 47 Be Polite 要有礼貌", "i": 1, "type": "reading", "en": "Everyone should be polite.", "zh": "每个人都应有礼貌。", "audio": "chuji_l47_01.mp3", "localAudio": "audio_chunks/chuji_l47_01.mp3", "b64": "", "src": "chuji"}, {"l": 347, "lt": "Lesson 47 Be Polite 要有礼貌", "i": 2, "type": "reading", "en": "Polite people show good manners.", "zh": "有礼貌的人展现良好的风度。", "audio": "chuji_l47_02.mp3", "localAudio": "audio_chunks/chuji_l47_02.mp3", "b64": "", "src": "chuji"}, {"l": 347, "lt": "Lesson 47 Be Polite 要有礼貌", "i": 3, "type": "reading", "en": "Moreover, they are popular.", "zh": "而且，他们受人欢迎。", "audio": "chuji_l47_03.mp3", "localAudio": "audio_chunks/chuji_l47_03.mp3", "b64": "", "src": "chuji"}, {"l": 347, "lt": "Lesson 47 Be Polite 要有礼貌", "i": 4, "type": "reading", "en": "On the other hand, rude people are looked down upon.", "zh": "另一方面，无礼的人则遭人轻视。", "audio": "chuji_l47_04.mp3", "localAudio": "audio_chunks/chuji_l47_04.mp3", "b64": "", "src": "chuji"}, {"l": 347, "lt": "Lesson 47 Be Polite 要有礼貌", "i": 5, "type": "reading", "en": "Rudeness shows poor education.", "zh": "无礼表示缺乏教养。", "audio": "chuji_l47_05.mp3", "localAudio": "audio_chunks/chuji_l47_05.mp3", "b64": "", "src": "chuji"}, {"l": 347, "lt": "Lesson 47 Be Polite 要有礼貌", "i": 6, "type": "reading", "en": "Therefore, why not be polite?", "zh": "因此，何不讲礼貌呢？", "audio": "chuji_l47_06.mp3", "localAudio": "audio_chunks/chuji_l47_06.mp3", "b64": "", "src": "chuji"}, {"l": 347, "lt": "Lesson 47 Be Polite 要有礼貌", "i": 7, "type": "reading", "en": "A simple \"Please,\" \"Thank you,\" or \"You're welcome,\" can make a big difference.", "zh": "一句简单的“请”、“谢谢”或“不客气”会带来很大的不同。", "audio": "chuji_l47_07.mp3", "localAudio": "audio_chunks/chuji_l47_07.mp3", "b64": "", "src": "chuji"}, {"l": 348, "lt": "Lesson 48 Don't Mention It 别客气", "i": 1, "type": "dialog", "en": "Excuse me, Chris. Could you pass me the sugar, please?", "zh": "对不起，克里斯。请你把糖递给我，好吗？", "audio": "chuji_l48_01.mp3", "localAudio": "audio_chunks/chuji_l48_01.mp3", "b64": "", "src": "chuji", "speaker": "Angell", "note": "说话人: Angell"}, {"l": 348, "lt": "Lesson 48 Don't Mention It 别客气", "i": 2, "type": "dialog", "en": "Sure. Here you are.", "zh": "没问题。拿去吧。", "audio": "chuji_l48_02.mp3", "localAudio": "audio_chunks/chuji_l48_02.mp3", "b64": "", "src": "chuji", "speaker": "Chris", "note": "说话人: Chris"}, {"l": 348, "lt": "Lesson 48 Don't Mention It 别客气", "i": 3, "type": "dialog", "en": "Thanks.", "zh": "谢谢。", "audio": "chuji_l48_03.mp3", "localAudio": "audio_chunks/chuji_l48_03.mp3", "b64": "", "src": "chuji", "speaker": "Angell", "note": "说话人: Angell"}, {"l": 348, "lt": "Lesson 48 Don't Mention It 别客气", "i": 4, "type": "dialog", "en": "Don't mention it.", "zh": "别客气。", "audio": "chuji_l48_04.mp3", "localAudio": "audio_chunks/chuji_l48_04.mp3", "b64": "", "src": "chuji", "speaker": "Chris", "note": "说话人: Chris"}, {"l": 349, "lt": "Lesson 49 Never Talk to Strangers 千万别跟陌生人说话", "i": 1, "type": "reading", "en": "Something strange happened to me yesterday.", "zh": "昨天有一件怪事发生在我身上。", "audio": "chuji_l49_01.mp3", "localAudio": "audio_chunks/chuji_l49_01.mp3", "b64": "", "src": "chuji"}, {"l": 349, "lt": "Lesson 49 Never Talk to Strangers 千万别跟陌生人说话", "i": 2, "type": "reading", "en": "On my way to school, I met a stranger.", "zh": "在上学途中，我遇见了一位陌生人。", "audio": "chuji_l49_02.mp3", "localAudio": "audio_chunks/chuji_l49_02.mp3", "b64": "", "src": "chuji"}, {"l": 349, "lt": "Lesson 49 Never Talk to Strangers 千万别跟陌生人说话", "i": 3, "type": "reading", "en": "He stopped me and said, \"You are Betty, aren't you?\"", "zh": "他拦住我并说道：“你是贝蒂，对吧？”", "audio": "chuji_l49_03.mp3", "localAudio": "audio_chunks/chuji_l49_03.mp3", "b64": "", "src": "chuji"}, {"l": 349, "lt": "Lesson 49 Never Talk to Strangers 千万别跟陌生人说话", "i": 4, "type": "reading", "en": "\"No,\" I replied.", "zh": "“不是，”我回答道。", "audio": "chuji_l49_04.mp3", "localAudio": "audio_chunks/chuji_l49_04.mp3", "b64": "", "src": "chuji"}, {"l": 349, "lt": "Lesson 49 Never Talk to Strangers 千万别跟陌生人说话", "i": 5, "type": "reading", "en": "He asked me, \"You know me, don't you?\"", "zh": "他问我：“你认识我，对不对？”", "audio": "chuji_l49_05.mp3", "localAudio": "audio_chunks/chuji_l49_05.mp3", "b64": "", "src": "chuji"}, {"l": 349, "lt": "Lesson 49 Never Talk to Strangers 千万别跟陌生人说话", "i": 6, "type": "reading", "en": "\"I don't,\" I answered.", "zh": "“我不认识，”我答道。", "audio": "chuji_l49_06.mp3", "localAudio": "audio_chunks/chuji_l49_06.mp3", "b64": "", "src": "chuji"}, {"l": 349, "lt": "Lesson 49 Never Talk to Strangers 千万别跟陌生人说话", "i": 7, "type": "reading", "en": "Then he said, \"You owe me $100, don't you?\"", "zh": "然后他说：“你欠我100美元，对不对？”", "audio": "chuji_l49_07.mp3", "localAudio": "audio_chunks/chuji_l49_07.mp3", "b64": "", "src": "chuji"}, {"l": 349, "lt": "Lesson 49 Never Talk to Strangers 千万别跟陌生人说话", "i": 8, "type": "reading", "en": "I ran away.", "zh": "我拔腿就跑。", "audio": "chuji_l49_08.mp3", "localAudio": "audio_chunks/chuji_l49_08.mp3", "b64": "", "src": "chuji"}, {"l": 349, "lt": "Lesson 49 Never Talk to Strangers 千万别跟陌生人说话", "i": 9, "type": "reading", "en": "At that moment, I remembered my mother's words: \"Never talk to strangers.\"", "zh": "就在那个时候，我想起母亲对我说过的话：“千万别跟陌生人说话。”", "audio": "chuji_l49_09.mp3", "localAudio": "audio_chunks/chuji_l49_09.mp3", "b64": "", "src": "chuji"}, {"l": 350, "lt": "Lesson 50 You're Sally, Aren't You? 你是萨莉，对不对？", "i": 1, "type": "dialog", "en": "Excuse me. You're Sally, aren't you?", "zh": "对不起。你是萨莉，对不对？", "audio": "chuji_l50_01.mp3", "localAudio": "audio_chunks/chuji_l50_01.mp3", "b64": "", "src": "chuji", "speaker": "George", "note": "说话人: George"}, {"l": 350, "lt": "Lesson 50 You're Sally, Aren't You? 你是萨莉，对不对？", "i": 2, "type": "dialog", "en": "Yes.", "zh": "对的。", "audio": "chuji_l50_02.mp3", "localAudio": "audio_chunks/chuji_l50_02.mp3", "b64": "", "src": "chuji", "speaker": "Sally", "note": "说话人: Sally"}, {"l": 350, "lt": "Lesson 50 You're Sally, Aren't You? 你是萨莉，对不对？", "i": 3, "type": "dialog", "en": "Hi! I'm George. You remember me, don't you?", "zh": "嗨！我是乔治。你还记得我吧，对不对？", "audio": "chuji_l50_03.mp3", "localAudio": "audio_chunks/chuji_l50_03.mp3", "b64": "", "src": "chuji", "speaker": "George", "note": "说话人: George"}, {"l": 350, "lt": "Lesson 50 You're Sally, Aren't You? 你是萨莉，对不对？", "i": 4, "type": "dialog", "en": "No.", "zh": "不记得了。", "audio": "chuji_l50_04.mp3", "localAudio": "audio_chunks/chuji_l50_04.mp3", "b64": "", "src": "chuji", "speaker": "Sally", "note": "说话人: Sally"}, {"l": 350, "lt": "Lesson 50 You're Sally, Aren't You? 你是萨莉，对不对？", "i": 5, "type": "dialog", "en": "We met at Bill's party.", "zh": "我们在比尔的宴会上见过面啊。", "audio": "chuji_l50_05.mp3", "localAudio": "audio_chunks/chuji_l50_05.mp3", "b64": "", "src": "chuji", "speaker": "George", "note": "说话人: George"}, {"l": 350, "lt": "Lesson 50 You're Sally, Aren't You? 你是萨莉，对不对？", "i": 6, "type": "dialog", "en": "Now I remember. Nice to see you again.", "zh": "现在我想起来了。很高兴再次见到你。", "audio": "chuji_l50_06.mp3", "localAudio": "audio_chunks/chuji_l50_06.mp3", "b64": "", "src": "chuji", "speaker": "Sally", "note": "说话人: Sally"}];